SHAILOG_COUNTRIES = 'United States, United Kingdom, Germany'
SHAILOG_INDUSTRIES = (
    'boutique digital agency, digital product studio, custom software development '
    'agency, web design agency, web development studio, app development agency, '
    'SaaS development agency, MVP development studio, UX design studio')


def seed_profiles(apps, schema_editor):
    """Two switchable targeting presets:

    1. "Backup — Buyer Targeting" — snapshot of whatever targeting the
       workspace had before this migration (the previous job, kept intact).
    2. "Shailog Tech — Agency Partners" — boutique agencies / software shops
       in the US, UK and Germany (agency ICP mode) — activated immediately:
       the write-through below flips AppSettings, so the very next pipeline
       cycle already hunts agency partners."""
    AppSettings = apps.get_model('core', 'AppSettings')
    SearchProfile = apps.get_model('core', 'SearchProfile')
    settings, _ = AppSettings.objects.get_or_create(pk=1)

    # 1 — keep the current job as a backup (never overwritten once created)
    SearchProfile.objects.get_or_create(
        name='Backup — Buyer Targeting',
        defaults={
            'description': 'Previous targeting, snapshotted before the agency-partner '
                           'profile was activated. Activate to restore the old job.',
            'target_countries': settings.target_countries or '',
            'target_industries': settings.target_industries or '',
            'target_cities': settings.target_cities or '',
            'icp_mode': settings.icp_mode or 'buyer',
            'is_active': False,
        },
    )

    # 2 — the new Shailog Tech profile (idempotent field refresh)
    profile, _ = SearchProfile.objects.get_or_create(
        name='Shailog Tech — Agency Partners',
        defaults={'description': ''},
    )
    profile.description = ('Boutique digital agencies & software shops in the US, UK and '
                           'Germany — white-label project partners for Shailog.')
    profile.target_countries = SHAILOG_COUNTRIES
    profile.target_industries = SHAILOG_INDUSTRIES
    profile.target_cities = ''
    profile.icp_mode = 'agency'
    profile.save()

    # 3 — classic buyer profile: operating businesses that need a website
    # (kept inactive; activating it is one click / one chat message)
    saas_builds, _ = SearchProfile.objects.get_or_create(
        name='Shailog — SaaS Builds (high level)',
        defaults={
            'description': 'High-level clients for custom SaaS builds: funded startups, '
                           'B2B SaaS, fintech/healthtech/edtech/AI companies and technology '
                           'operators — businesses that need a real platform, not a brochure.',
            'target_countries': SHAILOG_COUNTRIES,
            'target_industries': 'SaaS startup, B2B SaaS company, fintech startup, '
                                 'healthtech startup, edtech startup, AI startup, '
                                 'e-commerce brand, logistics technology company, '
                                 'proptech startup, marketplace startup',
            'target_cities': '',
            'icp_mode': 'buyer',
            'is_active': False,
        },
    )

    website_clients, _ = SearchProfile.objects.get_or_create(
        name='Shailog — Website Clients',
        defaults={
            'description': 'Operating businesses that need a website or better web presence — '
                           'the classic buyer ICP. Google Maps no-website discovery is ON in '
                           'this mode: businesses with no site at all are the hottest leads.',
            'target_countries': SHAILOG_COUNTRIES,
            'target_industries': '',  # empty = auto ICP buyer list (core.icp)
            'target_cities': '',
            'icp_mode': 'buyer',
            'is_active': False,
        },
    )

    # one-click switch, migration-time: write the profile through to the live
    # settings (same as SearchProfile.apply, minus the env-absorb of load())
    settings.target_countries = profile.target_countries
    settings.target_industries = profile.target_industries
    settings.target_cities = profile.target_cities
    settings.icp_mode = profile.icp_mode
    settings.save()
    SearchProfile.objects.exclude(pk=profile.pk).update(is_active=False)
    profile.is_active = True
    profile.save()


def unseed_profiles(apps, schema_editor):
    """Reverse: drop the seeded profiles (user-created ones stay)."""
    SearchProfile = apps.get_model('core', 'SearchProfile')
    SearchProfile.objects.filter(
        name__in=['Backup — Buyer Targeting', 'Shailog Tech — Agency Partners',
                  'Shailog — Website Clients', 'Shailog — SaaS Builds (high level)']).delete()


